import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  HEARTBEAT_INTERVAL_MS,
  LEASE_MS,
  MAX_ATTEMPTS,
  POLL_MS,
  RETRY_DELAY_MS,
  STEP_MS,
  TRANSIENT_ERROR,
  type JobRow,
} from './jobs.ts';

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const heartbeatStmt = db.prepare("INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at");
const claimStmt = db.prepare(
  `SELECT seq FROM jobs
   WHERE (status = 'queued' AND run_after <= ?) OR (status = 'running' AND lease_until < ?)
   ORDER BY seq ASC LIMIT 1`,
);
const startAttemptStmt = db.prepare(
  "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, lease_until = ?, updated_at = ? WHERE seq = ?",
);
const byseqStmt = db.prepare('SELECT * FROM jobs WHERE seq = ?');
const progressStmt = db.prepare("UPDATE jobs SET completed = ?, lease_until = ?, updated_at = ? WHERE seq = ? AND status = 'running'");
const retryStmt = db.prepare("UPDATE jobs SET status = 'queued', completed = 0, run_after = ?, lease_until = 0, updated_at = ? WHERE seq = ?");
const failStmt = db.prepare("UPDATE jobs SET status = 'failed', completed = 0, error = ?, result_output = NULL, lease_until = 0, updated_at = ? WHERE seq = ?");
const completeStmt = db.prepare(
  "UPDATE jobs SET status = 'completed', completed = ?, result_output = ?, error = NULL, lease_until = 0, updated_at = ? WHERE seq = ?",
);

function heartbeat(): void {
  heartbeatStmt.run(Date.now());
}

/** Claims the oldest runnable job (queued and due, or running with an expired lease) and starts an attempt. */
function claim(): JobRow | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const now = Date.now();
    const next = claimStmt.get(now, now) as { seq: number } | undefined;
    if (!next) {
      db.exec('COMMIT');
      return undefined;
    }
    startAttemptStmt.run(now + LEASE_MS, new Date(now).toISOString(), next.seq);
    const job = byseqStmt.get(next.seq) as unknown as JobRow;
    db.exec('COMMIT');
    return job;
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction was open
    }
    throw e;
  }
}

async function runAttempt(job: JobRow): Promise<void> {
  // Attempt n fails at its first step, before any progress, when n <= failAttempts.
  if (job.attempts <= job.fail_attempts) {
    await sleep(STEP_MS);
    const now = new Date();
    if (job.attempts < MAX_ATTEMPTS) {
      retryStmt.run(Date.now() + RETRY_DELAY_MS, now.toISOString(), job.seq);
    } else {
      failStmt.run(TRANSIENT_ERROR, now.toISOString(), job.seq);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return; // the lease expires and the job is processed again later
    progressStmt.run(step, Date.now() + LEASE_MS, new Date().toISOString(), job.seq);
  }
  completeStmt.run(job.steps, job.input.toUpperCase(), new Date().toISOString(), job.seq);
}

heartbeat();
const heartbeatTimer = setInterval(() => {
  try {
    heartbeat();
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}, HEARTBEAT_INTERVAL_MS);

console.log('worker started');
while (!stopping) {
  try {
    const job = claim();
    if (job) await runAttempt(job);
    else await sleep(POLL_MS);
  } catch (e) {
    console.error('worker error:', e);
    await sleep(POLL_MS);
  }
}

clearInterval(heartbeatTimer);
db.prepare("DELETE FROM heartbeats WHERE name = 'worker'").run();
db.close();
console.log('worker stopped');

