3	import { dirname } from 'node:path';
4	
5	const SCHEMA = `
6	CREATE TABLE IF NOT EXISTS jobs (
7	  seq INTEGER PRIMARY KEY AUTOINCREMENT,
8	  id TEXT NOT NULL UNIQUE,
9	  status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
10	  input TEXT NOT NULL,
11	  steps INTEGER NOT NULL,
12	  fail_attempts INTEGER NOT NULL,
13	  attempts INTEGER NOT NULL DEFAULT 0,
14	  completed INTEGER NOT NULL DEFAULT 0,
15	  result_output TEXT,
16	  error TEXT,
17	  run_after INTEGER NOT NULL DEFAULT 0,
18	  lease_until INTEGER NOT NULL DEFAULT 0,
19	  idempotency_key TEXT UNIQUE,
20	  request_fingerprint TEXT,
21	  created_at TEXT NOT NULL,
22	  updated_at TEXT NOT NULL
23	);
24	CREATE INDEX IF NOT EXISTS jobs_claim_idx ON jobs (status, run_after);
25	CREATE TABLE IF NOT EXISTS heartbeats (
26	  name TEXT PRIMARY KEY,
27	  at INTEGER NOT NULL
28	);
29	`;
30	
31	/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
32	export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
33	  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
34	  const db = new DatabaseSync(path);
