/** Job model, validation, and timing constants shared by the server and the worker. */

export const STEP_MS = 100;
/** A running attempt keeps a lease this long; a worker that dies loses it and the job is reclaimed. */
export const LEASE_MS = 3_000;
export const RETRY_DELAY_MS = 500;
export const MAX_ATTEMPTS = 3;
export const HEARTBEAT_INTERVAL_MS = 1_000;
export const WORKER_STALE_MS = 3_000;
export const POLL_MS = 200;
export const TRANSIENT_ERROR = 'transient failure';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as selected with `SELECT *`. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  result_output: string | null;
  error: string | null;
  run_after: number;
  lease_until: number;
  idempotency_key: string | null;
  request_fingerprint: string | null;
  created_at: string;
  updated_at: string;
}

/** The public JSON shape of a job. */
export interface JobJson {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function toJobJson(row: JobRow): JobJson {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export type ParseResult =
  | { ok: true; submission: Submission; idempotencyKey: string | undefined }
  | { ok: false; fields: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function checkInput(value: unknown, fields: FieldError[]): string | undefined {
  if (typeof value !== 'string') {
    fields.push({ field: 'input', message: 'is required and must be a string' });
    return undefined;
  }
  if (value.length < 1 || value.length > 1000) {
    fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
    return undefined;
  }
  if (value.trim() === '') {
    fields.push({ field: 'input', message: 'must not be only whitespace' });
    return undefined;
  }
  return value;
}

function checkInteger(body: Record<string, unknown>, key: 'steps' | 'failAttempts', min: number, max: number, fallback: number, fields: FieldError[]): number | undefined {
  const value = body[key];
  if (value === undefined) return fallback;
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    fields.push({ field: key, message: `must be an integer from ${min} to ${max}` });
    return undefined;
  }
  return value;
}

/** Validates a submission body and the optional Idempotency-Key header. Collects every problem it finds. */
export function parseSubmission(contentType: string | undefined, rawBody: string | undefined, idempotencyKey: string | undefined): ParseResult {
  const fields: FieldError[] = [];
  let body: Record<string, unknown> | undefined;

  const mediaType = contentType?.split(';', 1)[0]?.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (rawBody === undefined) {
    fields.push({ field: 'body', message: 'body is too large' });
  } else {
    let parsed: unknown;
    let isJson = true;
    try {
      parsed = JSON.parse(rawBody);
    } catch {
      isJson = false;
      fields.push({ field: 'body', message: 'body is not valid JSON' });
    }
    if (isJson) {
      if (isPlainObject(parsed)) body = parsed;
      else fields.push({ field: 'body', message: 'body must be a JSON object' });
    }
  }

  let submission: Submission | undefined;
  if (body) {
    for (const key of Object.keys(body)) {
      if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'is not a recognised field' });
    }
    const input = checkInput(body.input, fields);
    const steps = checkInteger(body, 'steps', 1, 20, 5, fields);
    const failAttempts = checkInteger(body, 'failAttempts', 0, 5, 0, fields);
    if (input !== undefined && steps !== undefined && failAttempts !== undefined) {
      submission = { input, steps, failAttempts };
    }
  }

  if (idempotencyKey !== undefined && !IDEMPOTENCY_KEY_RE.test(idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  if (fields.length > 0 || submission === undefined) {
    return { ok: false, fields: fields.length > 0 ? fields : [{ field: 'body', message: 'invalid request' }] };
  }
  return { ok: true, submission, idempotencyKey };
}

