4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Job tracker</title>
7	  <style>
8	    body { font-family: system-ui, sans-serif; margin: 2rem auto; max-width: 48rem; padding: 0 1rem; color: #222; }
9	    form { display: grid; grid-template-columns: 1fr 6rem 8rem auto; gap: .5rem; align-items: end; }
