11	    input { padding: .4rem; font: inherit; }
12	    button { padding: .45rem .9rem; font: inherit; }
13	    button:disabled { opacity: .6; }
14	    [data-testid="form-error"] { color: #b00020; margin: .75rem 0; min-height: 1.2em; white-space: pre-wrap; }
15	    [data-testid="job-list"] { list-style: none; padding: 0; }
16	    [data-testid="job-item"] { border: 1px solid #ddd; border-radius: 6px; padding: .6rem .8rem; margin-bottom: .5rem; display: grid; grid-template-columns: 7rem 5rem 1fr; gap: .5rem; }
17	    .job-id { grid-column: 1 / -1; font-size: .75rem; color: #777; font-family: monospace; }
18	    [data-testid="job-result"] { word-break: break-all; }
19	  </style>
20	</head>
21	<body>
22	  <h1>Job tracker</h1>
23	
24	  <form data-testid="job-form" id="job-form" novalidate>
25	    <label>Input
26	      <input data-testid="job-input" name="input" type="text" maxlength="1000" autocomplete="off">
27	    </label>
28	    <label>Steps
29	      <input data-testid="job-steps" name="steps" type="number" step="1" min="1" max="20" value="5">
30	    </label>
31	    <label>Fail attempts
32	      <input data-testid="job-fail-attempts" name="failAttempts" type="number" step="1" min="0" max="5" value="0">
33	    </label>
34	    <button data-testid="job-submit" type="submit">Submit</button>
35	  </form>
36	
37	  <div data-testid="form-error" role="alert"></div>
38	
39	  <h2>Jobs</h2>
40	  <ul data-testid="job-list" id="job-list"></ul>
41	
42	  <script>
43	    const form = document.getElementById('job-form');
44	    const errorBox = document.querySelector('[data-testid="form-error"]');
45	    const submitButton = document.querySelector('[data-testid="job-submit"]');
46	    const list = document.getElementById('job-list');
47	
48	    /** Sends a numeric field as a number when it looks numeric; otherwise sends the raw text so the API reports it. */
49	    function numericValue(text) {
50	      const trimmed = text.trim();
51	      if (trimmed === '') return undefined;
52	      const n = Number(trimmed);
53	      return Number.isFinite(n) ? n : trimmed;
54	    }
55	
56	    function describeError(data, status) {
57	      const err = data && data.error;
58	      if (!err) return 'Request failed with status ' + status + '.';
59	      const fields = Array.isArray(err.fields) ? err.fields.map((f) => f.field + ': ' + f.message) : [];
60	      return [err.message || 'Request failed.', ...fields].join('\n');
61	    }
62	
63	    form.addEventListener('submit', async (event) => {
64	      event.preventDefault();
65	      errorBox.textContent = '';
66	      const data = new FormData(form);
67	      const body = { input: String(data.get('input') ?? '') };
68	      const steps = numericValue(String(data.get('steps') ?? ''));
69	      const failAttempts = numericValue(String(data.get('failAttempts') ?? ''));
70	      if (steps !== undefined) body.steps = steps;
71	      if (failAttempts !== undefined) body.failAttempts = failAttempts;
72	
73	      submitButton.disabled = true;
74	      try {
75	        const res = await fetch('/api/jobs', {
76	          method: 'POST',
77	          headers: { 'content-type': 'application/json' },
78	          body: JSON.stringify(body),
79	        });
80	        let json = null;
81	        try { json = await res.json(); } catch { json = null; }
82	        if (res.status === 201 || res.status === 200) {
83	          form.elements.input.value = '';
84	          await refresh();
85	        } else {
86	          errorBox.textContent = describeError(json, res.status);
87	        }
88	      } catch (e) {
89	        errorBox.textContent = 'Could not reach the server: ' + e.message;
90	      } finally {
91	        submitButton.disabled = false;
92	      }
93	    });
94	
95	    function renderJob(job) {
96	      const li = document.createElement('li');
97	      li.setAttribute('data-testid', 'job-item');
98	      li.setAttribute('data-job-id', job.id);
99	
100	      const status = document.createElement('span');
101	      status.setAttribute('data-testid', 'job-status');
102	      status.textContent = job.status;
103	
104	      const progress = document.createElement('span');
105	      progress.setAttribute('data-testid', 'job-progress');
106	      progress.textContent = job.progress.completed + '/' + job.progress.total;
107	
108	      const result = document.createElement('span');
109	      result.setAttribute('data-testid', 'job-result');
110	      if (job.status === 'completed' && job.result) result.textContent = job.result.output;
111	      else if (job.status === 'failed') result.textContent = job.error || '';
112	      else result.textContent = '';
113	
114	      const id = document.createElement('span');
115	      id.className = 'job-id';
116	      id.textContent = job.id;
117	
118	      li.append(status, progress, result, id);
119	      return li;
120	    }
121	
122	    async function refresh() {
123	      try {
124	        const res = await fetch('/api/jobs', { cache: 'no-store' });
125	        if (!res.ok) return;
126	        const { jobs } = await res.json();
127	        list.replaceChildren(...jobs.map(renderJob));
128	      } catch {
129	        // keep the last rendered list; the next poll will retry
130	      }
131	    }
132	
133	    refresh();
134	    setInterval(refresh, 1000);
135	  </script>
136	</body>
